  // 0 when the grid fits horizontally -- the element exists either way.
  const hscroll = px('.ag-body-horizontal-scroll', 0) > 1 ? px('.ag-body-horizontal-scroll', 0) : 0;
  const avail = Math.max(160, widgetHeightPx() - 16);
  const rows = Math.max(1, Number(rowsOnPage) || 0);
  const needed = header + row * rows + pager + hscroll + FIT.chrome;
  div.style.height = Math.min(needed, avail) + 'px';
}

// Rows are not in the DOM yet when the data arrives, so the first call sizes from
// the fallbacks and this one corrects it once AG Grid has painted. The second pass
// also settles the case where growing the box removes the vertical scrollbar.
function fitGridHeightSoon(rowsOnPage) {
  fitGridHeight(rowsOnPage);
  requestAnimationFrame(function () {
    fitGridHeight(rowsOnPage);
    requestAnimationFrame(function () { fitGridHeight(rowsOnPage); });
  });
}

function renderGrid(model) {
  lastModel = model || lastModel;
  colDefaults = (model && model.fieldDefaults) || {};
  colOverrides = Object.assign({}, (model && model.fieldOverrides) || {});
  lastOverridesStr = JSON.stringify(colOverrides);
  colDescriptions = (model && model.fieldDescriptions) || {};
  const columnDefs = deriveColumns(model);
  lastColumnSignature = columnDefs.map(c => c.field).join(',');
  pendingSuccess = null;
  pendingValues = {};
  distinctCache = {};
  const gridOptions = {
    columnDefs,
    rowModelType: 'infinite',
    cacheBlockSize: pageSize,
    maxConcurrentDatasourceRequests: 1,
    pagination: true,
    paginationPageSize: pageSize,
    paginationPageSizeSelector: [25, 50, 100, 200, 500],
    defaultColDef: { sortable: true, resizable: true, filter: true, minWidth: 120, menuTabs: ['generalMenuTab', 'filterMenuTab', 'columnsMenuTab'], headerComponent: FieldInfoHeader },
    getMainMenuItems: buildMainMenuItems,
    datasource: makeDatasource(),
    animateRows: true,
    popupParent: document.body,
    onFilterChanged: function() { distinctCache = {}; },
    // Page size changed: rebuild so the block size matches it. A rebuild is how every
    // other shape change here is handled, and it re-asks for page one, which is where
    // a resized page should start anyway.
    onPaginationChanged: function() {
      if (!gridApi || typeof gridApi.paginationGetPageSize !== 'function') return;
      const size = gridApi.paginationGetPageSize();
      if (!size || size === pageSize) return;
      pageSize = size;
      renderGrid(lastModel);
    },
    onGridReady: function(params) { gridApi = params.api; }
  };
  const gridDiv = document.querySelector('#myGrid');
  if (!gridDiv) return;
  gridDiv.innerHTML = '';
  gridApi = agGrid.createGrid(gridDiv, gridOptions);
}

appsmith.onReady(function() {
  injectHeaderStyles();
  renderGrid(appsmith.model);
  fitGridHeightSoon(0);
  // The widget resizing in the editor changes --appsmith-ui-height and resizes the
  // iframe, so this catches both that and an ordinary window resize.
  window.addEventListener('resize', function () { fitGridHeightSoon(lastRowCount); });
  lastRefreshKey = Number(appsmith.model && appsmith.model.refreshKey) || 0;
  lastResponseTs = Number(appsmith.model && appsmith.model.responseTs) || 0;
  lastDistinctTs = Number(appsmith.model && appsmith.model.distinctRespTs) || 0;

  appsmith.onModelChange(function(model) {
    lastModel = model;
    // Distinct-values response for an open set filter. This update never carries
    // new rows or a column change, so deliver the values and stop.
    const dts = Number(model && model.distinctRespTs) || 0;
    if (dts !== lastDistinctTs) { lastDistinctTs = dts; deliverDistinct(model); return; }

    // Column renames changed elsewhere (e.g. reset) — refresh headers in place.
    const ovStr = JSON.stringify((model && model.fieldOverrides) || {});
    if (ovStr !== lastOverridesStr) {
      lastOverridesStr = ovStr;
      colOverrides = Object.assign({}, (model && model.fieldOverrides) || {});
      if (gridApi) gridApi.refreshHeader();
      return;
    }

    const key = Number(model && model.refreshKey) || 0;
    const newCols = deriveColumns(model);
    const newSig = newCols.map(function(c) { return c.field; }).join(',');

    // Filter or report changed => rebuild grid (forces fresh getRows).
    if (key !== lastRefreshKey || newSig !== lastColumnSignature) {
      lastRefreshKey = key;
      lastColumnSignature = newSig;
      lastResponseTs = Number(model && model.responseTs) || 0;
      renderGrid(model);
      return;
    }

    // Steady-state: deliver new rows to the pending getRows callback.
    const ts = Number(model && model.responseTs) || 0;
    if (ts !== lastResponseTs) { lastResponseTs = ts; deliverRows(model); }
  });
});
